public LevelGenAncientTree() {
        super(Codec.unit(FeatureConfiguration.NONE));
    }

@Override
    public boolean place(FeaturePlaceContext<NoneFeatureConfiguration> ctx) {
        var level = ctx.level();
        var pos = ctx.origin();
        var rand = ctx.random();
        var height = rand.nextInt(3) + 5;
        var trunkTop = pos.above(height);

        this.setBlock(level, pos, Blocks.AIR.defaultBlockState());
        //Roots
        var rootsAmount = rand.nextInt(4) + 5;
        for (var i = 0; i < rootsAmount; i++) {
            var length = rand.nextInt(3) + 3;
            var angle = 2F * (float) Math.PI * (i / (float) rootsAmount);
            var x = (float) Math.sin(angle) * length;
            var z = (float) Math.cos(angle) * length;

            var goal = pos.offset(Mth.floor(x), 0, Mth.floor(z));
            while (level.isStateAtPosition(goal, BlockStateBase::canBeReplaced)) {
                goal = goal.below();
                if (goal.distSqr(pos) >= 10 * 10)
                    break;
            }
            this.makeBranch(level, pos.above(rand.nextInt(1)), goal, ModBlocks.ANCIENT_BARK.defaultBlockState(), false);
        }

        //Trunk
        for (var x = 0; x <= 1; x++) {
            for (var z = 0; z <= 1; z++) {
                for (var i = height - (x + z) * (rand.nextInt(2) + 2); i >= 0; i--) {
                    var goal = pos.offset(x, i, z);
                    if (!level.isStateAtPosition(goal, s -> !TreeFeature.validTreePos(level, goal))) {
                        this.setBlock(level, goal, ModBlocks.ANCIENT_LOG.defaultBlockState().setValue(RotatedPillarBlock.AXIS, Axis.Y));
                    }
                }
            }
        }
        this.makeLeaves(level, trunkTop.above(rand.nextInt(2) - 1), ModBlocks.ANCIENT_LEAVES.defaultBlockState(), rand.nextInt(2) + 3, rand);

        //Branches
        var branchAmount = rand.nextInt(3) + 4;
        for (var i = 0; i < branchAmount; i++) {
            var length = rand.nextInt(2) + 3;
            var angle = 2F * (float) Math.PI * (i / (float) branchAmount);
            var x = (float) Math.sin(angle) * length;
            var z = (float) Math.cos(angle) * length;

            var goal = trunkTop.offset(Mth.floor(x), rand.nextInt(3) + 1, Mth.floor(z));
            this.makeBranch(level, trunkTop, goal, ModBlocks.ANCIENT_LOG.defaultBlockState(), true);
            this.makeLeaves(level, goal, ModBlocks.ANCIENT_LEAVES.defaultBlockState(), rand.nextInt(2) + 2, rand);
        }

        return true;
    }

private void makeBranch(WorldGenLevel level, BlockPos first, BlockPos second, BlockState state, boolean hasAxis) {
        var pos = second.offset(-first.getX(), -first.getY(), -first.getZ());
        var length = this.getHighestCoord(pos);
        var stepX = (float) pos.getX() / (float) length;
        var stepY = (float) pos.getY() / (float) length;
        var stepZ = (float) pos.getZ() / (float) length;

        for (var i = 0; i <= length; i++) {
            var goal = first.offset(Mth.floor(0.5F + i * stepX), Mth.floor(0.5F + i * stepY), Mth.floor(0.5F + i * stepZ));
            if (!level.isStateAtPosition(goal, s -> !TreeFeature.validTreePos(level, goal))) {
                if (hasAxis) {
                    var axis = this.getLogAxis(first, goal);
                    this.setBlock(level, goal, state.setValue(RotatedPillarBlock.AXIS, axis));
                } else {
                    this.setBlock(level, goal, state);
                }
            }
        }
    }

private void makeLeaves(WorldGenLevel level, BlockPos pos, BlockState state, int radius, RandomSource rand) {
        for (var x = -radius; x <= radius; x++) {
            for (var y = -radius; y <= radius; y++) {
                for (var z = -radius; z <= radius; z++) {
                    var goal = pos.offset(x, y, z);
                    if (pos.distSqr(goal) <= radius * radius + rand.nextInt(3) - 1) {
                        if (!level.isStateAtPosition(goal, s -> s.is(BlockTags.LEAVES))) {
                            if (level.isStateAtPosition(goal, st -> !st.is(BlockTags.LOGS) && st.getBlock() != Blocks.DIRT && st.getBlock() != Blocks.GRASS_BLOCK))
                                this.setBlock(level, goal, state);
                        }
                    }
                }
            }
        }
    }

private int getHighestCoord(BlockPos pos) {
        return Math.max(Mth.abs(pos.getX()), Math.max(Mth.abs(pos.getY()), Mth.abs(pos.getZ())));
    }

private Axis getLogAxis(BlockPos pos, BlockPos goal) {
        var axis = Axis.Y;
        var x = Math.abs(goal.getX() - pos.getX());
        var y = Math.abs(goal.getZ() - pos.getZ());
        var highest = Math.max(x, y);
        if (highest > 0) {
            if (x == highest) {
                axis = Axis.X;
            } else if (y == highest) {
                axis = Axis.Z;
            }
        }
        return axis;
    }

public LevelGenAuraBloom(Block block, int chance, boolean nether) {
        super(Codec.unit(FeatureConfiguration.NONE));
        this.block = block;
        this.chance = chance;
        this.nether = nether;
    }

@Override
    public boolean place(FeaturePlaceContext<NoneFeatureConfiguration> ctx) {
        var levelIn = ctx.level();
        var pos = ctx.origin();
        var rand = ctx.random();
        if (rand.nextInt(this.chance) != 0)
            return false;
        var startX = pos.getX() + rand.nextInt(16);
        var startZ = pos.getZ() + rand.nextInt(16);
        var any = false;
        for (var i = Mth.nextInt(rand, 3, 8); i > 0; i--) {
            var offX = startX + Mth.nextInt(rand, -5, 5);
            var offZ = startZ + Mth.nextInt(rand, -5, 5);
            if (this.nether) {
                var y = Mth.nextInt(rand, 0, 128);
                for (var off = 0; off < 64; off++) {
                    // try to find a good location in both directions of the random pos
                    if (this.tryPlace(levelIn, new BlockPos(offX, y - off, offZ)) || this.tryPlace(levelIn, new BlockPos(offX, y + off, offZ))) {
                        any = true;
                        break;
                    }
                }
            } else {
                var placePos = new BlockPos(offX, levelIn.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, offX, offZ), offZ);
                if (this.tryPlace(levelIn, placePos))
                    any = true;
            }
        }
        return any;
    }

private boolean tryPlace(WorldGenLevel level, BlockPos pos) {
        var state = this.block.defaultBlockState();
        if (state.canSurvive(level, pos)) {
            level.setBlock(pos, state, 3);
            var tile = level.getBlockEntity(pos);
            if (tile instanceof BlockEntityAuraBloom bloom)
                bloom.justGenerated = true;
            return true;
        }
        return false;
    }

public LevelGenNetherWartMushroom() {
        super(Codec.unit(FeatureConfiguration.NONE));
    }

@Override
    public boolean place(FeaturePlaceContext<NoneFeatureConfiguration> ctx) {
        var levelIn = ctx.level();
        var pos = ctx.origin();
        var rand = ctx.random();
        var height = rand.nextInt(5) + 4;
        if (rand.nextInt(10) == 0)
            height += 5;

        // Check if the stem has space
        for (var i = 1; i < height; i++) {
            var offset = pos.above(i);
            if (levelIn.isStateAtPosition(offset, s -> !TreeFeature.validTreePos(levelIn, offset)))
                return false;
        }

        // Place stem
        this.setBlock(levelIn, pos, Blocks.AIR.defaultBlockState());
        for (var i = 0; i < height; i++)
            this.placeIfPossible(levelIn, pos.above(i), Blocks.NETHER_WART_BLOCK);

        // Place hat
        var rad = 3;
        for (var x = -rad; x <= rad; x++) {
            for (var z = -rad; z <= rad; z++) {
                var absX = Math.abs(x);
                var absZ = Math.abs(z);
                if (absX <= 1 && absZ <= 1) {
                    this.placeIfPossible(levelIn, pos.offset(x, height, z), ModBlocks.NETHER_WART_MUSHROOM);
                } else if (absX <= 2 && absZ <= 2 && absX != absZ) {
                    this.placeIfPossible(levelIn, pos.offset(x, height - 1, z), ModBlocks.NETHER_WART_MUSHROOM);
                } else if (absX < rad - 1 || absZ < rad - 1 || absX == rad - 1 && absZ == rad - 1) {
                    this.placeIfPossible(levelIn, pos.offset(x, height - 2, z), ModBlocks.NETHER_WART_MUSHROOM);
                }
            }
        }
        return true;
    }

private void placeIfPossible(WorldGenLevel level, BlockPos pos, Block block) {
        if (level.isStateAtPosition(pos, s -> TreeFeature.validTreePos(level, pos)))
            level.setBlock(pos, block.defaultBlockState(), 19);
    }

